/* @autogenerated */
import { Component, inject } from '@angular/core';
import { Message } from 'app/features/notification/message/model/message.model';
import { MessageRepository } from 'app/features/notification/message/repository/message-repository.service';
import { ConfirmAction } from 'app/shared/toolkit/action/confirm-action';

@Component({ selector: 'message-view-delete-action', standalone: false, template: '' })
export class MessageViewDeleteActionComponent extends ConfirmAction<Message> {
  readonly name = 'delete';
  protected readonly scope = 'notification/message';
  protected readonly repository = inject(MessageRepository);

  protected execute([item]: Message[]) {
    return this.repository.deleteByKey(item.uid);
  }
}
